"""Procedural animated backgrounds — 100 % original, generated by code.

No game footage, trailers, logos or key art are used. Each style is an
"80s Florida / neon night" mood piece drawn with numpy + Pillow at half
resolution (FFmpeg upscales it; captions are rendered at full resolution).
Motion is slow and smooth: no strobing (photosensitivity-safe, < 3 Hz).
"""
from __future__ import annotations

import math
import subprocess
from pathlib import Path

import numpy as np
from PIL import Image, ImageDraw, ImageFilter

from .styles import hex_to_rgb

STYLE_NAMES = ("synth_sun", "palms", "waves", "bokeh_city", "police", "streaks")


def rgb(color: str) -> np.ndarray:
    return np.array(hex_to_rgb(color), dtype=np.float32) / 255.0


def mix(a: np.ndarray, b: np.ndarray, t: float) -> np.ndarray:
    return a * (1 - t) + b * t


def vertical_gradient(h: int, w: int, top: np.ndarray, bottom: np.ndarray, power: float = 1.0) -> np.ndarray:
    y = (np.linspace(0, 1, h, dtype=np.float32) ** power)[:, None, None]
    return np.broadcast_to(top * (1 - y) + bottom * y, (h, w, 3)).copy()


def radial(h: int, w: int, cx: float, cy: float, radius: float, sharp: float = 2.0) -> np.ndarray:
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    d = np.sqrt((xx - cx) ** 2 + (yy - cy) ** 2) / max(radius, 1)
    return np.clip(1 - d, 0, 1) ** sharp


def soft_disc(radius: int) -> np.ndarray:
    size = radius * 2 + 1
    yy, xx = np.mgrid[0:size, 0:size].astype(np.float32)
    d = np.sqrt((xx - radius) ** 2 + (yy - radius) ** 2) / max(radius, 1)
    edge = np.clip((1 - d) / 0.25, 0, 1)  # flat disc with a soft rim
    return (edge * (0.65 + 0.35 * (1 - d))).astype(np.float32)


def shift_x(layer: np.ndarray, shift: int) -> np.ndarray:
    """Shift a 2-D layer horizontally, filling with zeros (no wrap-around)."""
    if shift == 0:
        return layer
    out = np.zeros_like(layer)
    if shift > 0:
        out[:, shift:] = layer[:, :-shift]
    else:
        out[:, :shift] = layer[:, -shift:]
    return out


def blit_add(img: np.ndarray, sprite: np.ndarray, color: np.ndarray, cx: float, cy: float, alpha: float) -> None:
    h, w = img.shape[:2]
    r = sprite.shape[0] // 2
    x0, y0 = int(cx) - r, int(cy) - r
    x1, y1 = x0 + sprite.shape[1], y0 + sprite.shape[0]
    sx0, sy0 = max(0, -x0), max(0, -y0)
    sx1, sy1 = sprite.shape[1] - max(0, x1 - w), sprite.shape[0] - max(0, y1 - h)
    if sx1 <= sx0 or sy1 <= sy0:
        return
    region = img[max(0, y0):min(h, y1), max(0, x0):min(w, x1)]
    region += sprite[sy0:sy1, sx0:sx1, None] * color * alpha


def skyline(h: int, w: int, rng: np.random.Generator, base_y: float, color: np.ndarray, lights: list[np.ndarray]):
    """Generic city silhouette + window lights (RGBA float layers)."""
    sil = Image.new("L", (w, h), 0)
    d = ImageDraw.Draw(sil)
    win = np.zeros((h, w, 3), dtype=np.float32)
    flicker = []
    x = -10
    while x < w + 10:
        bw = int(rng.integers(26, 70))
        bh = int(rng.uniform(0.10, 0.34) * h)
        top = int(base_y - bh)
        d.rectangle([x, top, x + bw, h], fill=255)
        if rng.random() < 0.35:  # antenna
            d.line([x + bw // 2, top, x + bw // 2, top - rng.integers(8, 30)], fill=255, width=2)
        for wy in range(top + 8, h - 6, 11):
            for wx in range(x + 5, x + bw - 6, 9):
                if rng.random() < 0.28:
                    c = lights[int(rng.integers(0, len(lights)))]
                    win[wy:wy + 4, wx:wx + 4] = c * float(rng.uniform(0.35, 0.9))
                    if rng.random() < 0.08:
                        flicker.append((wy, wx, c, float(rng.uniform(0, 6.28))))
        x += bw + int(rng.integers(-4, 6))
    mask = np.asarray(sil, dtype=np.float32)[:, :, None] / 255.0
    return mask, win * mask, flicker


class Style:
    def __init__(self, palette: dict[str, str], seed: int, w: int, h: int):
        self.p = {k: rgb(v) for k, v in palette.items()}
        self.rng = np.random.default_rng(seed)
        self.w, self.h = w, h

    def frame(self, t: float) -> np.ndarray:  # float32 0..1
        raise NotImplementedError


class SynthSun(Style):
    def __init__(self, palette, seed, w, h):
        super().__init__(palette, seed, w, h)
        p, w, h = self.p, self.w, self.h
        self.horizon = int(h * 0.60)
        sky = vertical_gradient(self.horizon, w, p["sky_top"], p["sky_bottom"], 1.3)
        ground = vertical_gradient(h - self.horizon, w, p["sky_top"] * 0.55, p["sky_top"] * 0.12)
        self.base = np.concatenate([sky, ground], axis=0)
        self.cx, self.cy, self.r = w / 2, self.horizon - h * 0.13, w * 0.27
        self.base += radial(h, w, self.cx, self.cy, w * 0.75, 1.6)[..., None] * p["glow"] * 0.55
        yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
        self.sun_mask = (np.sqrt((xx - self.cx) ** 2 + (yy - self.cy) ** 2) <= self.r).astype(np.float32)
        self.sun_mask[self.horizon:] = 0
        ty = np.clip((yy - (self.cy - self.r)) / (2 * self.r), 0, 1)[..., None]
        self.sun_rgb = mix(p["accent"], p["glow"] * 0.6 + p["sky_bottom"] * 0.6, ty)
        self.yy = yy
        grid = Image.new("L", (w, h), 0)
        gd = ImageDraw.Draw(grid)
        for k in range(-14, 15):
            gd.line([w / 2 + k * 6, self.horizon, w / 2 + k * w * 0.16, h], fill=200, width=2)
        self.vgrid = np.asarray(grid.filter(ImageFilter.GaussianBlur(0.6)), dtype=np.float32)[..., None] / 255.0
        self.stars = [(self.rng.uniform(0, w), self.rng.uniform(0, self.horizon * 0.7), self.rng.uniform(0, 6.28))
                      for _ in range(70)]

    def frame(self, t):
        p, h, w = self.p, self.h, self.w
        img = self.base.copy()
        # sun with scrolling stripe cut-outs on its lower half
        rel = (self.yy - self.cy) / self.r
        phase = (rel * 7 - t * 0.6) % 1.0
        thickness = np.clip(rel, 0, 1) * 0.55
        stripes = np.where((rel > 0.05) & (phase < thickness), 0.0, 1.0)
        a = (self.sun_mask * stripes)[..., None]
        img = img * (1 - a) + self.sun_rgb * a
        # perspective grid
        grid_col = p["accent2"] * 0.9 + p["glow"] * 0.2
        img += self.vgrid * grid_col * 0.55
        n = 14
        for k in range(n):
            z = ((k + (t * 0.55) % 1.0) / n)
            y = int(self.horizon + (h - self.horizon) * z**2.1)
            if self.horizon < y < h - 1:
                img[y:y + 2] += grid_col * (0.25 + 0.6 * z)
        for sx, sy, ph in self.stars:
            v = 0.35 + 0.35 * math.sin(t * 1.7 + ph)
            img[int(sy), int(sx)] += v
        return img


class Palms(Style):
    def __init__(self, palette, seed, w, h):
        super().__init__(palette, seed, w, h)
        p = self.p
        self.horizon = int(h * 0.67)
        sky = vertical_gradient(self.horizon, w, p["sky_top"], p["sky_bottom"], 0.9)
        sea = vertical_gradient(h - self.horizon, w, p["sky_bottom"] * 0.45 + p["accent2"] * 0.15, p["sky_top"] * 0.3)
        self.base = np.concatenate([sky, sea], axis=0)
        self.base += radial(h, w, w * 0.5, self.horizon, w * 0.9, 1.8)[..., None] * p["glow"] * 0.6
        sun = radial(h, w, w * 0.5, self.horizon - 2, w * 0.16, 0.25)
        sun[self.horizon:] = 0
        self.base = self.base * (1 - sun[..., None] * 0.9) + p["accent"] * sun[..., None] * 0.95
        self.glints = [(self.rng.uniform(w * 0.25, w * 0.75), self.rng.uniform(self.horizon + 4, h),
                        self.rng.uniform(0, 6.28), self.rng.uniform(6, 26)) for _ in range(120)]
        self.palm_layers = [self._palm(int(w * 0.06), h, 0.62, 1), self._palm(int(w * 0.95), h, 0.55, -1),
                            self._palm(int(w * 0.84), h, 0.74, -1)]
        self.dark = p["sky_top"] * 0.25

    def _palm(self, base_x: int, h: int, height: float, lean: int) -> np.ndarray:
        w = self.w
        layer = Image.new("L", (w, h), 0)
        d = ImageDraw.Draw(layer)
        top = (base_x + lean * w * 0.12, h * (1 - height))
        pts = []
        for i in range(21):
            s = i / 20
            x = base_x + (top[0] - base_x) * s + lean * math.sin(s * math.pi) * w * 0.05
            y = h + (top[1] - h) * s
            pts.append((x, y))
        for i in range(20):
            width = 20 * (1 - i / 24) + 7
            d.line([pts[i], pts[i + 1]], fill=255, width=int(width))
            d.ellipse([pts[i][0] - width / 2, pts[i][1] - width / 2, pts[i][0] + width / 2, pts[i][1] + width / 2], fill=255)
        cx, cy = pts[-1]
        for k in range(11):
            ang = -math.pi * (-0.08 + 1.16 * k / 10) + self.rng.uniform(-0.1, 0.1)
            length = self.rng.uniform(95, 150)
            spine = []
            for j in range(13):
                s = j / 12
                droop = s * s * 55
                spine.append((cx + math.cos(ang) * length * s, cy + math.sin(ang) * length * s + droop))
            upper, lower = [], []
            for j, (x, y) in enumerate(spine):
                wdt = 13 * math.sin(math.pi * j / 12) ** 0.8
                upper.append((x, y - wdt))
                lower.append((x, y + wdt))
            d.polygon(upper + lower[::-1], fill=255)
        return np.asarray(layer, dtype=np.float32) / 255.0

    def frame(self, t):
        img = self.base.copy()
        for x, y, ph, length in self.glints:
            v = 0.5 + 0.5 * math.sin(t * 2.2 + ph)
            yi, x0 = int(y), int(x - length / 2 + 8 * math.sin(t * 0.7 + ph))
            img[yi, max(0, x0):min(self.w, x0 + int(length))] += self.p["glow"] * 0.35 * v
        sway = math.sin(t * 0.9) * 3
        for i, layer in enumerate(self.palm_layers):
            shift = int(round(sway * (1 + i * 0.4)))
            m = shift_x(layer, shift)[..., None]
            img = img * (1 - m) + self.dark * m
        return img


class Waves(Style):
    def __init__(self, palette, seed, w, h):
        super().__init__(palette, seed, w, h)
        p = self.p
        self.base = vertical_gradient(h, w, p["sky_top"], p["sky_bottom"], 1.1)
        self.base += radial(h, w, w * 0.7, h * 0.25, w * 0.8, 2.0)[..., None] * p["glow"] * 0.45
        self.x = np.arange(w, dtype=np.float32)[None, :]
        self.y = np.arange(h, dtype=np.float32)[:, None]
        cols = [p["accent2"], p["sky_bottom"], p["glow"], p["accent2"] * 0.6 + p["accent"] * 0.3, p["sky_top"]]
        self.bands = []
        for i in range(5):
            self.bands.append(dict(
                base=h * (0.50 + 0.09 * i), amp=self.rng.uniform(10, 26) * (1 + i * 0.25),
                lam=self.rng.uniform(160, 320), speed=self.rng.uniform(0.4, 0.9) * (1 if i % 2 else -1),
                phase=self.rng.uniform(0, 6.28), color=cols[i % len(cols)], alpha=0.20 + 0.10 * i))
        self.y0 = int(min(b["base"] - 2 * b["amp"] for b in self.bands))
        self.sparkles = [(self.rng.uniform(0, w), self.rng.uniform(0, h * 0.5), self.rng.uniform(0, 6.28))
                         for _ in range(40)]

    def frame(self, t):
        img = self.base.copy()
        low = img[self.y0:]
        ys = self.y[self.y0:]
        for b in self.bands:
            curve = (b["base"] + b["amp"] * np.sin(2 * np.pi * self.x / b["lam"] + b["speed"] * t * 2 + b["phase"])
                     + b["amp"] * 0.4 * np.sin(2 * np.pi * self.x / (b["lam"] * 0.37) - b["speed"] * t * 3))
            dist = ys - curve
            edge = np.clip(dist / 3.0, 0, 1)[..., None]
            shade = (1.0 - np.clip(dist / 260.0, 0, 0.45))[..., None]  # bands darken with depth
            low *= 1 - edge * b["alpha"]
            low += b["color"] * shade * edge * b["alpha"]
            low += np.clip(1 - np.abs(dist) / 2.0, 0, 1)[..., None] * self.p["glow"] * 0.3
        for sx, sy, ph in self.sparkles:
            v = max(0.0, math.sin(t * 1.3 + ph)) * 0.6
            img[int(sy), int(sx)] += v
        return img


class BokehCity(Style):
    def __init__(self, palette, seed, w, h):
        super().__init__(palette, seed, w, h)
        p = self.p
        self.base = vertical_gradient(h, w, p["sky_top"], p["sky_bottom"], 1.4)
        lights = [p["glow"], p["accent"], p["accent2"]]
        mask, win, self.flicker = skyline(h, w, self.rng, h * 0.98, p["sky_top"] * 0.2, lights)
        self.mask, self.win = mask, win
        self.discs = []
        for _ in range(26):
            r = int(self.rng.integers(10, 46))
            self.discs.append(dict(
                sprite=soft_disc(r), x=self.rng.uniform(0, w), y=self.rng.uniform(0, h * 0.8),
                vx=self.rng.uniform(-6, 6), vy=self.rng.uniform(-14, -3), color=lights[int(self.rng.integers(0, 3))],
                alpha=self.rng.uniform(0.10, 0.32), ph=self.rng.uniform(0, 6.28)))

    def frame(self, t):
        img = self.base.copy()
        for d in self.discs:
            x = (d["x"] + d["vx"] * t) % (self.w + 80) - 40
            y = (d["y"] + d["vy"] * t) % (self.h * 0.85 + 80) - 40
            blit_add(img, d["sprite"], d["color"], x, y, d["alpha"] * (0.75 + 0.25 * math.sin(t * 1.1 + d["ph"])))
        img = img * (1 - self.mask) + (self.p["sky_top"] * 0.18) * self.mask + self.win
        for wy, wx, c, ph in self.flicker:
            img[wy:wy + 4, wx:wx + 4] = c * (0.3 + 0.6 * (0.5 + 0.5 * math.sin(t * 0.8 + ph)))
        return img


class Police(Style):
    def __init__(self, palette, seed, w, h):
        super().__init__(palette, seed, w, h)
        p = self.p
        self.base = vertical_gradient(h, w, p["sky_top"], p["sky_bottom"], 1.2)
        self.red = radial(h, w, w * 0.18, h * 0.32, w * 0.95, 1.7)[..., None] * rgb("#ff2a2a")
        self.blue = radial(h, w, w * 0.82, h * 0.32, w * 0.95, 1.7)[..., None] * rgb("#2a5bff")
        mask, win, self.flicker = skyline(h, w, self.rng, h * 0.99, p["sky_top"], [p["accent"], rgb("#ffffff")])
        self.mask, self.win = mask, win * 0.6
        self.rain = [(self.rng.uniform(0, w), self.rng.uniform(0, h), self.rng.uniform(260, 420)) for _ in range(110)]

    def frame(self, t):
        s = math.sin(2 * math.pi * 0.85 * t)  # smooth 0.85 Hz alternation — no strobing
        img = self.base + self.red * (0.35 + 0.30 * s) + self.blue * (0.35 - 0.30 * s)
        pil = Image.fromarray(np.clip(img * 255, 0, 255).astype(np.uint8))
        d = ImageDraw.Draw(pil)
        for x, y, v in self.rain:
            yy = (y + v * t) % self.h
            xx = (x - 0.25 * v * t) % self.w
            d.line([xx, yy, xx - 3, yy + 14], fill=(150, 160, 190), width=1)
        img = np.asarray(pil, dtype=np.float32) / 255.0
        return img * (1 - self.mask) + self.p["sky_top"] * 0.1 * self.mask + self.win


class Streaks(Style):
    def __init__(self, palette, seed, w, h):
        super().__init__(palette, seed, w, h)
        p = self.p
        self.base = vertical_gradient(h, w, p["sky_top"], p["sky_top"] * 0.6 + p["sky_bottom"] * 0.4)
        self.center = radial(h, w, w / 2, h * 0.42, w * 0.7, 2.2)[..., None]
        cols = [p["glow"], p["accent"], p["accent2"], np.ones(3, dtype=np.float32)]
        self.lines = [(self.rng.uniform(0, 2 * math.pi), self.rng.uniform(0.25, 0.6), self.rng.uniform(0, 1),
                       cols[int(self.rng.integers(0, 4))]) for _ in range(110)]

    def frame(self, t):
        img = self.base + self.center * self.p["glow"] * (0.55 + 0.1 * math.sin(t * 2))
        pil = Image.fromarray(np.clip(img * 255, 0, 255).astype(np.uint8))
        d = ImageDraw.Draw(pil)
        cx, cy, rmax = self.w / 2, self.h * 0.42, math.hypot(self.w, self.h) * 0.6
        for ang, speed, ph, col in self.lines:
            z = (t * speed + ph) % 1.0
            r0 = (z**2) * rmax
            r1 = r0 + 6 + z * 70
            c = tuple(int(min(255, v * 255 * (0.25 + 0.75 * z))) for v in col)
            d.line([cx + math.cos(ang) * r0, cy + math.sin(ang) * r0, cx + math.cos(ang) * r1, cy + math.sin(ang) * r1],
                   fill=c, width=1 + int(z * 3))
        return np.asarray(pil, dtype=np.float32) / 255.0


STYLES = {"synth_sun": SynthSun, "palms": Palms, "waves": Waves, "bokeh_city": BokehCity, "police": Police,
          "streaks": Streaks}


def make_style(name: str, palette: dict[str, str], seed: int, w: int = 540, h: int = 960) -> Style:
    return STYLES[name](palette, seed, w, h)


def to_uint8(img: np.ndarray) -> np.ndarray:
    return (np.clip(img, 0, 1) * 255 + 0.5).astype(np.uint8)


def render_clip(style: str, palette: dict[str, str], duration: float, out_path: Path, *, seed: int = 0,
                fps: int = 30, w: int = 540, h: int = 960, time_offset: float = 0.0) -> Path:
    """Render one background clip to an intermediate H.264 file."""
    gen = make_style(style, palette, seed, w, h)
    frames = max(1, int(round(duration * fps)))
    cmd = ["ffmpeg", "-y", "-loglevel", "error", "-f", "rawvideo", "-pix_fmt", "rgb24", "-s", f"{w}x{h}",
           "-r", str(fps), "-i", "-", "-c:v", "libx264", "-preset", "ultrafast", "-crf", "12",
           "-pix_fmt", "yuv420p", str(out_path)]
    proc = subprocess.Popen(cmd, stdin=subprocess.PIPE)
    try:
        for i in range(frames):
            proc.stdin.write(to_uint8(gen.frame(time_offset + i / fps)).tobytes())
    finally:
        proc.stdin.close()
        code = proc.wait()
    if code != 0:
        raise RuntimeError(f"ffmpeg failed rendering background {style}")
    return out_path
